import fs from "node:fs"
import path from "node:path"
import type { QuartzEmitterPlugin } from "../quartz/plugins/types"
import { FilePath, joinSegments } from "../quartz/util/path"
import { languageOf } from "./bilingual"

// Generated by brand/build.sh; see brand/README.md.
const BRAND = path.join("brand", "out")

// Output path → file in brand/out. Quartz's own icon.png and og-image.png are kept out of
// the core Static emitter by ignorePatterns, so these are the only ones on the site.
const FILES: Record<string, string> = {
  "favicon.ico": "favicon.ico",
  "static/icon.png": "icon.png",
  "static/favicon-16.png": "favicon-16.png",
  "static/favicon-32.png": "favicon-32.png",
  "static/favicon-48.png": "favicon-48.png",
  "static/apple-touch-icon.png": "apple-touch-icon.png",
  "static/og-image.png": "og-image-ru.png",
  "static/og-image-ru.png": "og-image-ru.png",
  "static/og-image-en.png": "og-image-en.png",
}

// Named so that Head.tsx leaves the og:image tags to this plugin: each language gets its own card.
export const GardenBrand: QuartzEmitterPlugin = () => ({
  name: "CustomOgImages",
  async *emit(ctx) {
    for (const [dest, src] of Object.entries(FILES)) {
      const out = joinSegments(ctx.argv.output, dest) as FilePath
      await fs.promises.mkdir(path.dirname(out), { recursive: true })
      await fs.promises.copyFile(path.join(BRAND, src), out)
      yield out
    }
  },
  async *partialEmit() {},
  externalResources: (ctx) => {
    const base = `https://${ctx.cfg.configuration.baseUrl}`
    return {
      additionalHead: [
        // The 16 px icon is a simplified drawing, so browsers should not downscale the large one.
        <link rel="icon" type="image/png" sizes="16x16" href="/static/favicon-16.png" />,
        <link rel="icon" type="image/png" sizes="32x32" href="/static/favicon-32.png" />,
        <link rel="icon" type="image/png" sizes="48x48" href="/static/favicon-48.png" />,
        <link rel="apple-touch-icon" href="/static/apple-touch-icon.png" />,
        (pageData) => {
          const image = `${base}/static/og-image-${languageOf(pageData.slug) ?? "ru"}.png`
          return (
            <>
              <meta property="og:image" content={image} />
              <meta property="og:image:url" content={image} />
              <meta property="og:image:type" content="image/png" />
              <meta property="og:image:width" content="1200" />
              <meta property="og:image:height" content="630" />
              <meta name="twitter:image" content={image} />
            </>
          )
        },
      ],
    }
  },
})
